1	"use client";
2	
3	import { useMemo, useState } from "react";
4	import { useActionState } from "react";
5	import { orderServer } from "@/lib/actions";
6	import { AppLogo } from "@/components/ui/AppLogo";
7	import { VPS_TERMS, vpsTermPriceCents, vpsEffectiveMonthly } from "@/lib/billing-terms";
8	
9	type Plan = {
10	  id: string; name: string; cpuCores: number; ramMB: number; diskGB: number;
11	  bandwidthTB: number; priceCents: number; storageTier: string;
12	};
13	type Image = {
14	  id: string; slug: string; name: string; category: string; family: string;
15	  version: string; logo: string; minRamMB: number; minDiskGB: number;
16	  licenseRequired: boolean; featured: boolean;
17	};
18	type NodeOpt = { id: string; name: string; publicIp: string };
19	
20	const money = (c: number) => `$${(c / 100).toFixed(2)}`;
21	const CATS = [
22	  { key: "PLAIN_OS", label: "Plain OS" },
23	  { key: "CONTROL_PANEL", label: "Control panel" },
24	  { key: "APPLICATION", label: "Applications" },
25	] as const;
26	
27	function LogoChip({ image }: { image: Image }) {
28	  return <AppLogo family={image.logo || image.family} name={image.name} size={32} />;
29	}
30	
31	function Stepper({ step, steps }: { step: number; steps: string[] }) {
32	  return (
33	    <div className="mb-6 flex flex-wrap items-center gap-2 text-xs">
34	      {steps.map((s, i) => (
35	        <div key={s} className="flex items-center gap-2">
36	          <span
37	            className={`flex h-6 w-6 items-center justify-center rounded-full border text-[11px] font-semibold ${
38	              i === step ? "border-brand-400 bg-brand-500/20 text-brand-200"
39	                : i < step ? "border-emerald-500/40 bg-emerald-500/15 text-emerald-300"
40	                  : "border-white/10 text-slate-500"
41	            }`}
42	          >
43	            {i < step ? "✓" : i + 1}
44	          </span>
45	          <span className={i === step ? "text-white" : "text-slate-500"}>{s}</span>
46	          {i < steps.length - 1 && <span className="mx-1 text-slate-700">→</span>}
47	        </div>
48	      ))}
49	    </div>
50	  );
51	}
52	
53	export function DeployWizard({
54	  plans, images, nodes, sshKeys, isAdmin, balanceCents, dedicatedIpAvailable, dedicatedIpPriceCents,
55	}: {
56	  plans: Plan[]; images: Image[]; nodes: NodeOpt[];
57	  sshKeys: { id: string; name: string }[]; isAdmin: boolean; balanceCents: number;
58	  dedicatedIpAvailable?: boolean; dedicatedIpPriceCents?: number;
59	}) {
60	  const [state, action, pending] = useActionState(orderServer, {} as { error?: string });
61	  const multiNode = nodes.length > 1;
62	  const steps = ["Plan", ...(multiNode ? ["Location"] : []), "Install", "Add-ons", "Access", "Review"];
63	  const [step, setStep] = useState(0);
64	
65	  const [planId, setPlanId] = useState(plans[0]?.id ?? "");
66	  const [nodeId, setNodeId] = useState(nodes[0]?.id ?? "");
67	  const [imageId, setImageId] = useState(images.find((i) => i.category === "PLAIN_OS")?.id ?? images[0]?.id ?? "");
68	  const [cat, setCat] = useState<string>("PLAIN_OS");
69	  const [q, setQ] = useState("");
70	  const [addons, setAddons] = useState({ malware: false, backup: false, docker: false });
71	  const [dedicatedIp, setDedicatedIp] = useState(false);
72	  const [hostname, setHostname] = useState("");
73	  const [rootPw, setRootPw] = useState("");
74	  const [pubKey, setPubKey] = useState("");
75	  const [free, setFree] = useState(false);
76	  const [termMonths, setTermMonths] = useState(1);
77	
78	  const plan = plans.find((p) => p.id === planId);
79	  const image = images.find((i) => i.id === imageId);
80	
81	  const families = useMemo(() => {
82	    const inCat = images.filter((i) => i.category === cat && (q === "" || i.name.toLowerCase().includes(q.toLowerCase())));
83	    if (cat !== "PLAIN_OS") return inCat.map((i) => ({ family: i.slug, name: i.name, versions: [i] }));
84	    const map = new Map<string, { family: string; name: string; versions: Image[] }>();
85	    for (const i of inCat) {
86	      const g = map.get(i.family) ?? { family: i.family, name: i.name, versions: [] };
87	      g.versions.push(i);
88	      map.set(i.family, g);
89	    }
90	    return [...map.values()];
91	  }, [images, cat, q]);
92	
93	  const hostnameValid = /^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/i.test(hostname) && hostname.length >= 3;
94	  const planMeetsImage = !!plan && !!image && plan.ramMB >= image.minRamMB && plan.diskGB >= image.minDiskGB;
95	  const ipMonthly = dedicatedIp ? dedicatedIpPriceCents ?? 0 : 0;
96	  const dueCents = free ? 0 : plan ? vpsTermPriceCents(plan.priceCents, termMonths) + ipMonthly * termMonths : 0;
97	  const canDeploy = !!planId && !!imageId && hostnameValid && planMeetsImage;
98	  const isLast = step === steps.length - 1;
99	  const curLabel = steps[step];
100	
101	  return (
102	    <form action={action}>
103	      <input type="hidden" name="planId" value={planId} />
104	      <input type="hidden" name="osTemplateId" value={imageId} />
105	      <input type="hidden" name="hostname" value={hostname} />
106	      {multiNode && <input type="hidden" name="nodeId" value={nodeId} />}
107	      <input type="hidden" name="addon_malware" value={addons.malware ? "1" : "0"} />
108	      <input type="hidden" name="addon_backup" value={addons.backup ? "1" : "0"} />
109	      <input type="hidden" name="addon_docker" value={addons.docker ? "1" : "0"} />
110	      <input type="hidden" name="dedicatedIp" value={dedicatedIp ? "1" : "0"} />
111	      {pubKey.trim() && <input type="hidden" name="sshPublicKey" value={pubKey.trim()} />}
112	      {isAdmin && free && <input type="hidden" name="free" value="1" />}
113	      <input type="hidden" name="termMonths" value={termMonths} />
114	
115	      <div className="card">
116	        <Stepper step={step} steps={steps} />
117	        {state?.error && (
118	          <div className="mb-4 rounded-xl border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-300">{state.error}</div>
119	        )}
120	
121	        {curLabel === "Plan" && (
122	          <div>
123	            <h2 className="mb-4 font-semibold">Choose your resources</h2>
124	            <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
125	              {plans.map((p, i) => (
126	                <button type="button" key={p.id} onClick={() => setPlanId(p.id)}
127	                  className={`card p-4 text-left transition ${planId === p.id ? "!border-brand-400 ring-1 ring-brand-400" : "hover:border-white/20"}`}>
128	                  <div className="flex items-center justify-between">
129	                    <span className="font-semibold">{p.name}</span>
130	                    {i === Math.floor(plans.length / 2) && <span className="rounded-full bg-brand-500/20 px-2 py-0.5 text-[10px] text-brand-200">popular</span>}
131	                  </div>
132	                  <p className="mt-1 text-2xl font-bold">{money(p.priceCents)}<span className="text-xs font-normal text-slate-400">/mo</span></p>
133	                  <ul className="mt-2 space-y-0.5 text-xs text-slate-400">
134	                    <li>{p.cpuCores} vCPU · {p.ramMB / 1024} GB RAM</li>
135	                    <li>{p.diskGB} GB {p.storageTier === "hdd" ? "HDD" : "NVMe"}</li>
136	                    <li>{p.bandwidthTB} TB bandwidth</li>
137	                  </ul>
138	                </button>
139	              ))}
140	            </div>
141	          </div>
142	        )}
143	
144	        {curLabel === "Location" && (
145	          <div>
146	            <h2 className="mb-4 font-semibold">Choose a location</h2>
147	            <div className="grid gap-3 sm:grid-cols-2">
148	              {nodes.map((n) => (
149	                <button type="button" key={n.id} onClick={() => setNodeId(n.id)}
150	                  className={`card p-4 text-left transition ${nodeId === n.id ? "!border-brand-400 ring-1 ring-brand-400" : "hover:border-white/20"}`}>
151	                  <span className="font-semibold">{n.name}</span>
152	                  <p className="mt-1 text-xs text-slate-400">{n.publicIp}</p>
153	                </button>
154	              ))}
155	            </div>
156	          </div>
157	        )}
158	
159	        {curLabel === "Install" && (
160	          <div>
161	            <h2 className="mb-1 font-semibold">Choose what to install</h2>
162	            <p className="mb-4 text-sm text-slate-400">Operating system, control panel, or application. You can reinstall later.</p>
163	            <input className="input mb-3" placeholder="Search OS, panels, or apps…" value={q} onChange={(e) => setQ(e.target.value)} />
164	            <div className="mb-4 flex gap-2">
165	              {CATS.map((c) => (
166	                <button type="button" key={c.key} onClick={() => { setCat(c.key); setQ(""); }}
167	                  className={`rounded-full px-3 py-1.5 text-xs font-semibold transition ${cat === c.key ? "bg-white text-navy-950" : "bg-white/[0.06] text-slate-300 hover:bg-white/10"}`}>
168	                  {c.label}
169	                </button>
170	              ))}
171	            </div>
172	            <div className="grid gap-2.5 sm:grid-cols-2">
173	              {families.map((f) => {
174	                const selectedInFamily = f.versions.find((v) => v.id === imageId);
175	                const active = !!selectedInFamily;
176	                const display = selectedInFamily ?? f.versions[0];
177	                return (
178	                  <div key={f.family} className={`card flex items-center gap-3 p-3 transition ${active ? "!border-brand-400 ring-1 ring-brand-400" : "hover:border-white/20"}`}>
179	                    <LogoChip image={display} />
180	                    <button type="button" className="flex-1 text-left" onClick={() => setImageId(display.id)}>
181	                      <span className="text-sm font-medium">{f.name}</span>
182	                      {display.licenseRequired && <span className="ml-2 rounded bg-amber-500/15 px-1.5 py-0.5 text-[10px] text-amber-300">license</span>}
183	                      {display.featured && <span className="ml-2 rounded bg-brand-500/15 px-1.5 py-0.5 text-[10px] text-brand-200">popular</span>}
184	                    </button>
185	                    {f.versions.length > 1 ? (
186	                      <select className="input w-auto py-1 text-xs" value={selectedInFamily?.id ?? ""} onChange={(e) => setImageId(e.target.value)}>
187	                        <option value="" disabled>version</option>
188	                        {f.versions.map((v) => <option key={v.id} value={v.id}>{v.version}</option>)}
189	                      </select>
190	                    ) : (
191	                      <button type="button" onClick={() => setImageId(display.id)}
192	                        className={`h-4 w-4 rounded-full border ${active ? "border-brand-400 bg-brand-500" : "border-white/20"}`} aria-label={`Select ${f.name}`} />
193	                    )}
194	                  </div>
195	                );
196	              })}
197	            </div>
198	            {image && !planMeetsImage && (
199	              <p className="mt-3 text-xs text-amber-300">{image.name} needs ≥ {image.minRamMB / 1024} GB RAM and {image.minDiskGB} GB disk. Go back and pick a larger plan.</p>
200	            )}
201	            {image?.licenseRequired && (
202	              <p className="mt-3 text-xs text-slate-400">{image.name} requires a paid license from the vendor — enter it after the server boots.</p>
203	            )}
204	          </div>
205	        )}
206	
207	        {curLabel === "Add-ons" && (
208	          <div>
209	            <h2 className="mb-1 font-semibold">Additional features</h2>
210	            <p className="mb-4 text-sm text-slate-400">You can add or remove these later in your VPS dashboard.</p>
211	            <div className="grid gap-3 sm:grid-cols-3">
212	              {[
213	                { k: "malware", t: "Malware scanner", tag: "Free", d: "Blocks malicious files and suspicious activity (ClamAV)." },
214	                { k: "backup", t: "Daily auto-backups", tag: "Included", d: "Nightly snapshots to separate storage for easy restore." },
215	                { k: "docker", t: "Docker manager", tag: "Free", d: "Docker + Compose preinstalled to deploy containers instantly." },
216	              ].map((a) => {
217	                const on = (addons as any)[a.k];
218	                return (
219	                  <button type="button" key={a.k} onClick={() => setAddons((s) => ({ ...s, [a.k]: !on }))}
220	                    className={`card p-4 text-left transition ${on ? "!border-brand-400 ring-1 ring-brand-400" : "hover:border-white/20"}`}>
221	                    <div className="mb-2 flex items-center justify-between">
222	                      <span className="rounded bg-emerald-500/15 px-1.5 py-0.5 text-[10px] text-emerald-300">{a.tag}</span>
223	                      <span className={`h-4 w-4 rounded border ${on ? "border-brand-400 bg-brand-500" : "border-white/20"}`} />
224	                    </div>
225	                    <p className="text-sm font-semibold">{a.t}</p>
226	                    <p className="mt-1 text-xs text-slate-400">{a.d}</p>
227	                  </button>
228	                );
229	              })}
230	            </div>
231	            {dedicatedIpAvailable && (
232	              <button
233	                type="button"
234	                onClick={() => setDedicatedIp((v) => !v)}
235	                className={`card mt-3 flex w-full items-center justify-between p-4 text-left transition ${dedicatedIp ? "!border-brand-400 ring-1 ring-brand-400" : "hover:border-white/20"}`}
236	              >
237	                <div>
238	                  <div className="flex items-center gap-2">
239	                    <span className="text-sm font-semibold">Dedicated IPv4 address</span>
240	                    <span className="rounded bg-brand-500/15 px-1.5 py-0.5 text-[10px] text-brand-200">
241	                      +{money(dedicatedIpPriceCents ?? 0)}/mo
242	                    </span>
243	                  </div>
244	                  <p className="mt-1 text-xs text-slate-400">
245	                    Your own public IP — no shared ports. Ideal for VPNs, mail, game servers, and SSL. Free IPv6 is always included.
246	                  </p>
247	                </div>
248	                <span className={`h-4 w-4 shrink-0 rounded border ${dedicatedIp ? "border-brand-400 bg-brand-500" : "border-white/20"}`} />
249	              </button>
250	            )}
251	          </div>
252	        )}
253	
254	        {curLabel === "Access" && (
255	          <div className="space-y-4">
256	            <h2 className="font-semibold">Secure your VPS access</h2>
257	            <div>
258	              <label className="label">Hostname</label>
259	              <input className="input max-w-sm" value={hostname} onChange={(e) => setHostname(e.target.value.toLowerCase())} placeholder="my-server" />
260	              {!hostnameValid && hostname.length > 0 && <p className="mt-1 text-xs text-red-300">3–40 chars, letters/digits/hyphens.</p>}
261	            </div>
262	            <div className="grid gap-4 md:grid-cols-2">
263	              <div className="card">
264	                <p className="mb-2 text-sm font-semibold">Root password <span className="text-xs font-normal text-slate-500">optional</span></p>
265	                <div className="flex gap-2">
266	                  <input className="input" value={rootPw} onChange={(e) => setRootPw(e.target.value)} placeholder="auto-generated if blank" />
267	                  <button type="button" className="btn-secondary shrink-0"
268	                    onClick={() => setRootPw(Array.from(crypto.getRandomValues(new Uint8Array(9))).map((b) => "abcdefghjkmnpqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ23456789"[b % 54]).join(""))}>
269	                    Generate
270	                  </button>
271	                </div>
272	                <p className="mt-2 text-xs text-slate-500">Blank = we generate a strong one, shown on your server page.</p>
273	              </div>
274	              <div className="card">
275	                <p className="mb-2 text-sm font-semibold">SSH key <span className="text-xs font-normal text-slate-500">optional</span></p>
276	                <textarea className="input h-20 font-mono text-xs" value={pubKey} onChange={(e) => setPubKey(e.target.value)} placeholder="ssh-ed25519 AAAA…" />
277	                <p className="mt-2 text-xs text-slate-500">
278	                  {sshKeys.length > 0 ? `Your ${sshKeys.length} saved key(s) are injected automatically. Add another here.` : "Paste a public key for passwordless login. Saved to your account."}
279	                </p>
280	              </div>
281	            </div>
282	            {isAdmin && (
283	              <label className="flex items-center gap-2 text-sm text-brand-300">
284	                <input type="checkbox" checked={free} onChange={(e) => setFree(e.target.checked)} />
285	                Deploy free of charge (admin — no billing, never expires)
286	              </label>
287	            )}
288	          </div>
289	        )}
290	
291	        {curLabel === "Review" && (
292	          <div>
293	            {!free && plan && (
294	              <div className="mb-5">
295	                <h2 className="mb-1 font-semibold">Billing term</h2>
296	                <p className="mb-3 text-sm text-slate-400">Commit longer, save more.</p>
297	                <div className="grid gap-2.5 sm:grid-cols-2 lg:grid-cols-4">
298	                  {VPS_TERMS.map((t) => {
299	                    const total = vpsTermPriceCents(plan.priceCents, t.months);
300	                    const perMo = vpsEffectiveMonthly(plan.priceCents, t.months);
301	                    const on = termMonths === t.months;
302	                    return (
303	                      <button
304	                        type="button"
305	                        key={t.months}
306	                        onClick={() => setTermMonths(t.months)}
307	                        className={`card relative p-3.5 text-left transition ${on ? "!border-brand-400 ring-1 ring-brand-400" : "hover:border-white/20"}`}
308	                      >
309	                        {t.discountPct > 0 && (
310	                          <span className="absolute right-2 top-2 rounded-full bg-emerald-500/20 px-1.5 py-0.5 text-[10px] font-semibold text-emerald-300">
311	                            −{t.discountPct}%
312	                          </span>
313	                        )}
314	                        <p className="text-sm font-semibold">{t.label}</p>
315	                        <p className="mt-1 text-lg font-bold">{money(perMo)}<span className="text-xs font-normal text-slate-400">/mo</span></p>
316	                        <p className="mt-0.5 text-[11px] text-slate-500">{money(total)} billed {t.months === 1 ? "monthly" : `every ${t.short}`}</p>
317	                      </button>
318	                    );
319	                  })}
320	                </div>
321	              </div>
322	            )}
323	            <h2 className="mb-4 font-semibold">Review &amp; deploy</h2>
324	            <dl className="space-y-2 text-sm">
325	              <Row k="Plan" v={plan ? `${plan.name} · ${plan.cpuCores} vCPU / ${plan.ramMB / 1024} GB / ${plan.diskGB} GB` : "—"} />
326	              <Row k="Install" v={image ? `${image.name}${image.version ? " " + image.version : ""}` : "—"} />
327	              {multiNode && <Row k="Location" v={nodes.find((n) => n.id === nodeId)?.name ?? "auto"} />}
328	              <Row k="Add-ons" v={[addons.malware && "Malware scanner", addons.backup && "Daily backups", addons.docker && "Docker", dedicatedIp && "Dedicated IPv4"].filter(Boolean).join(", ") || "None"} />
329	              <Row k="Hostname" v={hostname || "—"} />
330	              <div className="divider" />
331	              <Row k="Due today" v={<span className="text-base font-semibold">{money(dueCents)}</span>} />
332	              <Row k="Wallet balance" v={money(balanceCents)} />
333	              <Row k="Balance after" v={<span className={balanceCents - dueCents < 0 ? "text-red-300" : "text-emerald-300"}>{money(balanceCents - dueCents)}</span>} />
334	            </dl>
335	            {!free && balanceCents < dueCents && <p className="mt-3 text-sm text-amber-300">Insufficient balance — add funds on the Billing page first.</p>}
336	          </div>
337	        )}
338	
339	        <div className="mt-6 flex items-center justify-between">
340	          <button type="button" className="btn-ghost" disabled={step === 0} onClick={() => setStep((s) => Math.max(0, s - 1))}>← Back</button>
341	          {!isLast ? (
342	            <button type="button" className="btn-primary" disabled={curLabel === "Install" && (!image || !planMeetsImage)} onClick={() => setStep((s) => s + 1)}>Continue →</button>
343	          ) : (
344	            <button className="btn-primary px-6" disabled={pending || !canDeploy}>{pending ? "Deploying…" : `Deploy — ${money(dueCents)}`}</button>
345	          )}
346	        </div>
347	      </div>
348	    </form>
349	  );
350	}
351	
352	function Row({ k, v }: { k: string; v: React.ReactNode }) {
353	  return (
354	    <div className="flex items-center justify-between">
355	      <dt className="text-slate-400">{k}</dt>
356	      <dd className="text-right">{v}</dd>
357	    </div>
358	  );
359	}
