1	import { db } from "@/lib/db";
2	import { requireUser } from "@/lib/auth";
3	import { PageHeader, EmptyState } from "@/components/ui/primitives";
4	import { DeployWizard } from "@/components/customer/DeployWizard";
5	import { capacitySnapshot } from "@/lib/capacity";
6	import { DEDICATED_IP_PRICE_CENTS } from "@/lib/dedicated-ip";
7	
8	export const dynamic = "force-dynamic";
9	
10	export default async function DeployPage() {
11	  const user = await requireUser();
12	  const [plans, images, sshKeys, nodes, capacity, freeIps] = await Promise.all([
13	    db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
14	    db.osTemplate.findMany({ where: { active: true }, orderBy: [{ sortOrder: "asc" }, { name: "asc" }] }),
15	    db.sshKey.findMany({ where: { userId: user.id }, select: { id: true, name: true, publicKey: true } }),
16	    db.node.findMany({ where: { enabled: true }, select: { id: true, name: true, publicIp: true } }),
17	    capacitySnapshot(),
18	    db.dedicatedIp.count({ where: { status: "FREE" } }),
19	  ]);
20	
21	  return (
22	    <div className="space-y-6">
23	      <PageHeader title="Deploy a server" sub="NVMe-backed KVM virtual machines, live in under two minutes." />
24	      {capacity.nearCapacity && (
25	        <div className="rounded-2xl border border-amber-500/30 bg-amber-500/10 px-4 py-3 text-sm text-amber-300">
26	          <span className="font-semibold">Host is filling up.</span> We&apos;re at{" "}
27	          {Math.round(capacity.ramUtilization * 100)}% of committed RAM. Larger plans may be briefly unavailable.
28	        </div>
29	      )}
30	      {plans.length === 0 || images.length === 0 ? (
31	        <EmptyState
32	          title="Deployments are temporarily unavailable"
33	          sub="No active plans or images are configured. Please check back soon or contact support."
34	        />
35	      ) : (
36	        <DeployWizard
37	          plans={plans.map((p) => ({
38	            id: p.id,
39	            name: p.name,
40	            cpuCores: p.cpuCores,
41	            ramMB: p.ramMB,
42	            diskGB: p.diskGB,
43	            bandwidthTB: p.bandwidthTB,
44	            priceCents: p.priceCents,
45	            storageTier: p.storageTier,
46	          }))}
47	          images={images.map((o) => ({
48	            id: o.id,
49	            slug: o.slug,
