"use client";

import { useEffect } from "react";
import { AppLogo } from "@/components/ui/AppLogo";

export type PickImage = {
  id: string;
  name: string;
  family: string;
  version: string;
  logo: string;
  minRamMB: number;
  minDiskGB: number;
  licenseRequired: boolean;
  featured: boolean;
};

export type FamilyGroup = {
  family: string;
  name: string;
  logo: string;
  versions: PickImage[];
};

/**
 * Hostinger-style version picker. Opens as a styled overlay (not a native select)
 * listing every version of an OS family as a selectable row. Picking one calls
 * onSelect(id) and the parent closes the modal.
 */
export function VersionPickerModal({
  group,
  selectedId,
  plan,
  onSelect,
  onClose,
}: {
  group: FamilyGroup;
  selectedId: string;
  plan?: { ramMB: number; diskGB: number };
  onSelect: (id: string) => void;
  onClose: () => void;
}) {
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => e.key === "Escape" && onClose();
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onClose]);

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4" role="dialog" aria-modal="true" aria-label={`Choose ${group.name} version`}>
      <div className="absolute inset-0 bg-navy-950/80 backdrop-blur-sm" onClick={onClose} />
      <div className="card relative z-10 w-full max-w-md !p-5 max-h-[80vh] overflow-y-auto">
        <div className="mb-4 flex items-center gap-3">
          <AppLogo family={group.logo || group.family} name={group.name} size={40} />
          <div className="min-w-0">
            <h3 className="truncate font-semibold">{group.name}</h3>
            <p className="text-xs text-slate-400">Choose a version to install</p>
          </div>
          <button
            type="button"
            onClick={onClose}
            aria-label="Close"
            className="ml-auto flex h-8 w-8 shrink-0 items-center justify-center rounded-lg text-slate-400 hover:bg-white/[0.06] hover:text-white"
          >
            ✕
          </button>
        </div>

        <div className="space-y-2">
          {group.versions.map((v) => {
            const on = v.id === selectedId;
            const fits = plan ? plan.ramMB >= v.minRamMB && plan.diskGB >= v.minDiskGB : true;
            return (
              <button
                type="button"
                key={v.id}
                onClick={() => onSelect(v.id)}
                className={`flex w-full items-center gap-3 rounded-xl border px-3.5 py-3 text-left transition ${
                  on
                    ? "border-brand-400 bg-brand-500/10 ring-1 ring-brand-400"
                    : "border-white/10 bg-white/[0.02] hover:border-white/25 hover:bg-white/[0.05]"
                }`}
              >
                <div className="min-w-0 flex-1">
                  <div className="flex items-center gap-2">
                    <span className="text-sm font-medium">{v.version || v.name}</span>
                    {v.featured && <span className="rounded bg-brand-500/15 px-1.5 py-0.5 text-[10px] text-brand-200">popular</span>}
                    {v.licenseRequired && <span className="rounded bg-amber-500/15 px-1.5 py-0.5 text-[10px] text-amber-300">license</span>}
                  </div>
                  {!fits && (
                    <p className="mt-0.5 text-[11px] text-amber-300">
                      Needs ≥ {v.minRamMB / 1024} GB RAM / {v.minDiskGB} GB disk
                    </p>
                  )}
                </div>
                <span
                  className={`flex h-5 w-5 shrink-0 items-center justify-center rounded-full border text-[11px] ${
                    on ? "border-brand-400 bg-brand-500 text-white" : "border-white/20"
                  }`}
                >
                  {on ? "✓" : ""}
                </span>
              </button>
            );
          })}
        </div>
      </div>
    </div>
  );
}

